import{_ as t,o as a,c as d,ag as o}from"./chunks/framework.C5oN-8Wt.js";const m=JSON.parse('{"title":"测距模拟器","description":"","frontmatter":{},"headers":[],"relativePath":"v0.4.0-alpha/modules/range_simulator/index.md","filePath":"v0.4.0-alpha/modules/range_simulator/index.md"}'),r={name:"v0.4.0-alpha/modules/range_simulator/index.md"};function n(c,e,i,h,l,s){return a(),d("div",null,[...e[0]||(e[0]=[o('<h1 id="测距模拟器" tabindex="-1">测距模拟器 <a class="header-anchor" href="#测距模拟器" aria-label="Permalink to &quot;测距模拟器&quot;">​</a></h1><p>适用：v0.4.0-alpha · GNU Radio 3.10.12.0<br> 模块类型：<code>range_simulator</code> · 模块定义版本：1</p><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>从局部平面的 <code>[x,y]</code> 位置，计算到三个固定锚点的欧氏距离，并可在每个距离上叠加独立高斯误差。这是在电脑中生成测距数据的模型，不接收卫星信号，也不控制真实测距硬件。</p><h2 id="典型接线" tabindex="-1">典型接线 <a class="header-anchor" href="#典型接线" aria-label="Permalink to &quot;典型接线&quot;">​</a></h2><p><code>坐标发生器.position → 测距模拟器.position</code>，再接 <code>测距模拟器.ranges → 二维定位解算器.ranges</code>。输入一个两分量位置 item，输出同一历元的三个距离；输入输出均使用米。</p><p>下表为内置默认参数下的端口。带路数、元素类型或 vlen 的模块会随参数改变流端口。</p><table tabindex="0"><thead><tr><th>方向</th><th>端口</th><th>数据类型</th><th>单位 / 形状</th></tr></thead><tbody><tr><td>输入</td><td><code>position</code>（二维位置）</td><td><code>numeric_f64</code></td><td>m；vlen=2</td></tr><tr><td>输出</td><td><code>ranges</code>（三锚点测距）</td><td><code>numeric_f64</code></td><td>m；vlen=3</td></tr></tbody></table><h2 id="参数怎么用" tabindex="-1">参数怎么用 <a class="header-anchor" href="#参数怎么用" aria-label="Permalink to &quot;参数怎么用&quot;">​</a></h2><p><code>anchors_m</code> 是按顺序排列的六项列表 <code>[x1,y1,x2,y2,x3,y3]</code>，表示三个锚点各自的 x、y，而不是六个锚点。输出三个分量也按这个锚点顺序排列。</p><p>模拟器与解算器各有自己的锚点设置，程序不自动同步。入门对照应显式设成相同列表；使用不同列表是在研究模型不一致，不能当作正确接线的基准。</p><p><code>noise_std_m</code> 是测距误差的标准差，单位 m；设为零表示不加测距噪声。标准差描述随机误差的尺度，不是每个距离固定增加的偏差，也不是误差最大值或最终定位误差。<code>seed</code> 决定伪随机序列；模块按 item、再按锚点顺序取噪声，重新准备会重置种子与状态。相同输入、种子和设置用于重现同一软件试验。</p><p>参数范围和需一起修改的字段见下表。</p><p>内置默认值如下；本机设置可为<strong>新实例</strong>指定其他默认值，打开已有工程保留工程参数。</p><table tabindex="0"><thead><tr><th>参数</th><th>内置默认值</th><th>取值与约束</th><th>修改时机</th></tr></thead><tbody><tr><td>三锚点坐标 [x1,y1,x2,y2,x3,y3] (m)<br><code>anchors_m</code></td><td><code>[0, 0, 10, 0, 0, 10]</code></td><td>按字段类型填写，见下文说明</td><td>重新准备</td></tr><tr><td>测距高斯噪声标准差 (m)<br><code>noise_std_m</code></td><td><code>0</code></td><td>范围 0 至 3.4028234663852886e+38</td><td>重新准备</td></tr><tr><td>固定随机种子<br><code>seed</code></td><td><code>0</code></td><td>范围 0 至 2147483647</td><td>重新准备</td></tr></tbody></table><h2 id="在线修改与重新准备" tabindex="-1">在线修改与重新准备 <a class="header-anchor" href="#在线修改与重新准备" aria-label="Permalink to &quot;在线修改与重新准备&quot;">​</a></h2><p>计算参数或结构变化后，先停止，再重新准备和运行。</p><p>本模块不提供在线参数修改。需要从相同随机起点作对照时，停止、修改、重新准备后再运行；修改草稿不能让已有数据改用新噪声设置。</p><h2 id="示例与观察" tabindex="-1">示例与观察 <a class="header-anchor" href="#示例与观察" aria-label="Permalink to &quot;示例与观察&quot;">​</a></h2><h3 id="用三段距离解出平面坐标" tabindex="-1">用三段距离解出平面坐标 <a class="header-anchor" href="#用三段距离解出平面坐标" aria-label="Permalink to &quot;用三段距离解出平面坐标&quot;">​</a></h3><p><a href="../../../downloads/v0.4.0-alpha/01-position-from-ranges.cnsproj" download>下载 01-position-from-ranges.cnsproj</a></p><p>在 PC 上打开工程，按 F5 运行。有限运行可将参考源样本数设为 64 item；重新打开工程后需再次运行以取得数据。</p><p>用三段距离解出平面坐标</p><ul><li>静态位置 (3,4) m 的三距为 5、√65、√45 m；显式比较 x/y 分量，定位残差接近 0。</li></ul><p><a href="./../../learn/01-position-from-ranges/">三距定位课</a>先关闭噪声。锚点为 <code>(0,0)</code>、<code>(10,0)</code>、<code>(0,10)</code> m，位置为 <code>(3,4)</code> m 时，手算距离为 <code>5、√65、√45 m</code>。捕获标量曲线须分别选择 <code>ranges</code> 的 0、1、2 分量，不将三个距离拼成运动轨迹。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>加入噪声后，距离会被自动限制为非负吗？</strong> 不会。负测距触发任务失败，不截负、不取绝对值或补零掩盖问题。高斯误差没有固定最大偏差，不能保证任意加噪设置都能持续定位。</p><p><strong>三个输出为什么不是三个采样时刻？</strong> 它们共同描述同一位置历元到三个锚点的距离，共享该 item 的实际时间。</p><h2 id="递进实验" tabindex="-1">递进实验 <a class="header-anchor" href="#递进实验" aria-label="Permalink to &quot;递进实验&quot;">​</a></h2><ul><li><a href="./../../learn/01-position-from-ranges/">10 三段距离求位置</a></li></ul>',30)])])}const u=t(r,[["render",n]]);export{m as __pageData,u as default};
